SELECT 100.0 * SUM(CASE WHEN p.height < 180 AND EXISTS (
    SELECT 1 FROM Player_Attributes pa
    WHERE pa.player_api_id = p.player_api_id AND pa.overall_rating > 70
) THEN 1 ELSE 0 END) / COUNT(*) AS percentage FROM Player p;

SELECT COALESCE(SUM(CASE WHEN eye_colour_id = 7 THEN 1 ELSE 0 END),0) - COALESCE(SUM(CASE WHEN eye_colour_id = 1 THEN 1 ELSE 0 END),0) AS difference
FROM superhero
WHERE weight_kg IS NULL OR weight_kg = 0;

