SELECT ( (SELECT COUNT(*) FROM cards WHERE isStorySpotlight = 1 AND isTextless = 0) * 100.0 ) / (SELECT COUNT(*) FROM cards) AS percentage, id
FROM cards
WHERE isStorySpotlight = 1 AND isTextless = 0;

SELECT ((SELECT COUNT(*) FROM cards WHERE isStorySpotlight = 1 AND isTextless = 1) * 100.0) / (SELECT COUNT(*) FROM cards WHERE isStorySpotlight = 1) AS percentage, id
FROM cards
WHERE isStorySpotlight = 1 AND isTextless = 1;

SELECT (SUM(CASE WHEN gender = 'M' THEN 1 ELSE 0 END) * 100.0) / NULLIF(COUNT(*),0) AS percentage_male
FROM client
WHERE district_id IN (
  SELECT district_id FROM district
  WHERE lower(A3) = 'south bohemia'
    AND CAST(A4 AS INTEGER) = (
      SELECT MAX(CAST(A4 AS INTEGER)) FROM district WHERE lower(A3) = 'south bohemia'
    )
);

SELECT (SUM(CASE WHEN lower(ec.name) = 'blue' THEN 1 ELSE 0 END) * 100.0) / COUNT(*) AS percentage_blue
FROM superhero s
LEFT JOIN eye_colour ec ON s.eye_colour_id = ec.id;

SELECT CASE WHEN COUNT(*) = 0 THEN 0.0 ELSE (SUM(CASE WHEN lower(c.colour) = 'blue' THEN 1 ELSE 0 END) * 100.0) / COUNT(*) END AS percentage_blue
FROM superhero s
LEFT JOIN colour c ON s.eye_colour_id = c.id;

answer_sql:
SELECT CASE WHEN COUNT(*) = 0 THEN 0.0 ELSE (SUM(CASE WHEN lower(c.colour) = 'blue' THEN 1 ELSE 0 END) * 100.0) / COUNT(*) END AS percentage_blue
FROM superhero s
LEFT JOIN colour c ON s.eye_colour_id = c.id;
